import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create container
  const root = new Group();

  // Compute plane size from atlas region (aspect ratio)
  const region = { width: 512, height: 320 };
  const aspect = region.width / region.height;
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously, assign when ready
  let tex;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((t) => {
      tex = t;
      material.map = texture(t);
      material.needsUpdate = true;
    })
    .catch(() => {
      // texture load failure – keep material empty
    });

  // Apply cinematic primitives if any
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const result = fn(root, prim.params);
        if (result?.timeline) primitiveCleanups.push(result.timeline);
        if (result?.cleanup) primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // No interactive handlers for this node
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (tex) tex.dispose();
    // Kill any GSAP timelines (none used here but safe)
    gsap.globalTimeline.clear();
    // Run primitive cleanups
    for (const c of primitiveCleanups) {
      if (typeof c === 'function') c();
    }
  };

  return root;
}
